 explicit StateProgramLoadService(Kind k):StateProgramLoadService(k,Input{}){}StateProgramLoadService(Kind k,Input in):kind_(k),input_(in),parent_(k==Kind::CommitSingle?StateProgramChangeTask::Kind::CommitSingle:k==Kind::CommitMulti?StateProgramChangeTask::Kind::CommitMulti:StateProgramChangeTask::Kind::LoadSingle){summary_.presentation=in.presentation;}
