 const StateProgramLoadDataService*data()const{return data_?&*data_:nullptr;}const StateReloadVoiceService*voices()const{return voices_?&*voices_:nullptr;}const StateReloadService*reload()const{return reload_?&*reload_:nullptr;}const SerialForegroundService*serial()const{return serial_?&*serial_:nullptr;}
