 std::optional<StatePresetAddressTask>preset_;std::optional<StateProgramTask>index_;std::optional<StateProgramLoadDataService>data_;std::optional<PeriodicTask>mark_;std::optional<StateReloadVoiceService>voices_;std::optional<PartLookupTask>lookup_;std::optional<StateChannelTask>channel_;std::optional<StateReloadService>reload_;std::optional<MidiOutputTask>midi_;std::optional<SerialForegroundService>serial_;
